// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.robustnessimport timber.log.Timberimport android.Manifestimport android.app.Activityimport android.content.Contextimport android.content.pm.PackageManagerimport android.net.Uriimport androidx.core.content.ContextCompatimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlow/** * NOUS — Camera Permission Manager (Module 6 v4.2 — HIGH Priority Patch). * * Manages the camera permission state machine with graceful fallback to * Android 13+ Photo Picker, per v4.2 §"Camera Permission Handling". * * ## State Machine (per v4.2) * * ``` * 1. User says "NOUS, what's this?" (camera command) *    ↓ * 2. NOUS checks CAMERA permission: *    - GRANTED → open camera, start vision pipeline *    - Not granted → show permission dialog with rationale *    ↓ * 3. If user denies: *    - DENIED_ONCE → show rationale + retry dialog *    - DENIED_TWICE → offer photo picker fallback *    - DENIED_PERMANENTLY → guide to Settings (can't prompt again) *    ↓ * 4. Photo Picker fallback (Android 13+): *    - User picks a photo from gallery *    - Vision pipeline runs on selected photo (one-shot, not live) *    - No CAMERA permission needed * ``` * * ## Privacy * *  - Camera frames are processed on-device and never uploaded. *  - Photo picker returns a content URI — NOUS gets temporary read access, *    not permanent gallery access. *  - User can revoke camera permission anytime in Settings. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.2-final.md">§Camera Permission Handling</a> */class CameraPermissionManager(    private val context: Context,) {    private val _permissionState = MutableStateFlow(CameraPermissionState.NOT_REQUESTED)    val permissionState: StateFlow<CameraPermissionState> = _permissionState.asStateFlow()    /** Count of times the user has denied the permission (for state machine). */    @Volatile    private var denialCount: Int = 0    /** True if the user has selected "Don't ask again" (Android system level). */    @Volatile    private var shouldShowRationale: Boolean = false    /**     * Check the current camera permission state.     *     * @param activity the current activity (for checking shouldShowRequestPermissionRationale).     * @return the current permission state.     */    fun checkPermissionState(activity: Activity?): CameraPermissionState {        val granted = ContextCompat.checkSelfPermission(            context,            Manifest.permission.CAMERA,        ) == PackageManager.PERMISSION_GRANTED        return when {            granted -> {                _permissionState.value = CameraPermissionState.GRANTED                CameraPermissionState.GRANTED            }            activity != null && denialCount >= 2 && !activity.shouldShowRequestPermissionRationale(                Manifest.permission.CAMERA            ) -> {                // User denied twice + selected "Don't ask again"                _permissionState.value = CameraPermissionState.DENIED_PERMANENTLY                CameraPermissionState.DENIED_PERMANENTLY            }            denialCount >= 2 -> {                _permissionState.value = CameraPermissionState.DENIED_TWICE                CameraPermissionState.DENIED_TWICE            }            denialCount == 1 -> {                _permissionState.value = CameraPermissionState.DENIED_ONCE                CameraPermissionState.DENIED_ONCE            }            else -> {                _permissionState.value = CameraPermissionState.NOT_REQUESTED                CameraPermissionState.NOT_REQUESTED            }        }    }    /**     * Called when the user grants the permission.     */    fun onPermissionGranted() {        Timber.tag(TAG).i("Camera permission granted.")        _permissionState.value = CameraPermissionState.GRANTED        denialCount = 0    }    /**     * Called when the user denies the permission.     */    fun onPermissionDenied() {        denialCount++        Timber.tag(TAG).w("Camera permission denied (count=$denialCount).")        _permissionState.value = when {            denialCount >= 3 -> CameraPermissionState.DENIED_PERMANENTLY            denialCount == 2 -> CameraPermissionState.DENIED_TWICE            else -> CameraPermissionState.DENIED_ONCE        }    }    /**     * Get the rationale message to show to the user (before requesting permission).     *     * @return the rationale message, or null if no rationale needed.     */    fun getRationaleMessage(): String? = when (_permissionState.value) {        CameraPermissionState.NOT_REQUESTED -> """            NOUS needs camera access to see what you're pointing at.            Camera frames are processed on-device and never uploaded.            Enable camera?        """.trimIndent()        CameraPermissionState.DENIED_ONCE -> """            I still need camera access to see what you're pointing at.            Without camera, I can't identify objects, read text, or scan documents.            Camera frames never leave your device.            Try again?        """.trimIndent()        CameraPermissionState.DENIED_TWICE -> """            It seems you don't want to grant camera access. That's okay!            You can still pick a photo from your gallery instead.            Or, if you change your mind, you can enable camera in Settings later.        """.trimIndent()        CameraPermissionState.DENIED_PERMANENTLY -> """            Camera access is blocked. To enable it:            Settings → Apps → NOUS → Permissions → Camera → Allow.            Or, pick a photo from your gallery instead.        """.trimIndent()        CameraPermissionState.GRANTED -> null  // Already granted, no rationale needed.    }    /**     * Get the TTS message to speak to the user.     */    fun getSpokenMessage(): String? = when (_permissionState.value) {        CameraPermissionState.NOT_REQUESTED ->            "I need camera access to see what you're pointing at. Camera frames never leave your device."        CameraPermissionState.DENIED_ONCE ->            "I still need camera access. Without it, I can't see. Please grant camera permission."        CameraPermissionState.DENIED_TWICE ->            "Camera access denied. You can pick a photo from your gallery instead, or enable camera in Settings."        CameraPermissionState.DENIED_PERMANENTLY ->            "Camera access is blocked. Please enable it in Settings, or pick a photo from your gallery."        CameraPermissionState.GRANTED -> null    }    /**     * Check if the photo picker fallback should be offered.     *     * Photo picker is offered when:     *  - User denied camera twice or more     *  - OR user denied permanently     *  - AND device supports Photo Picker (Android 13+)     */    fun shouldOfferPhotoPicker(): Boolean {        return (_permissionState.value == CameraPermissionState.DENIED_TWICE ||                _permissionState.value == CameraPermissionState.DENIED_PERMANENTLY)    }    /**     * Check if the device supports Android 13+ Photo Picker.     */    fun isPhotoPickerSupported(): Boolean {        return android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU    }    /**     * Get the recovery action for the current permission state.     */    fun getRecoveryAction(): CameraRecoveryAction = when (_permissionState.value) {        CameraPermissionState.GRANTED -> CameraRecoveryAction.PROCEED_WITH_CAMERA        CameraPermissionState.NOT_REQUESTED,        CameraPermissionState.DENIED_ONCE -> CameraRecoveryAction.REQUEST_PERMISSION        CameraPermissionState.DENIED_TWICE -> {            if (isPhotoPickerSupported()) {                CameraRecoveryAction.OFFER_PHOTO_PICKER            } else {                CameraRecoveryAction.GUIDE_TO_SETTINGS            }        }        CameraPermissionState.DENIED_PERMANENTLY -> {            if (isPhotoPickerSupported()) {                CameraRecoveryAction.OFFER_PHOTO_PICKER_OR_SETTINGS            } else {                CameraRecoveryAction.GUIDE_TO_SETTINGS            }        }    }    /**     * Reset the permission state (for testing or when user re-enables in Settings).     */    fun reset() {        denialCount = 0        shouldShowRationale = false        _permissionState.value = CameraPermissionState.NOT_REQUESTED    }    /** Get denial count (for debugging). */    fun getDenialCount(): Int = denialCount    private companion object {        private const val TAG = "CameraPermission"    }}// ──────────────────────────────────────────────────────────────────────────/** Camera permission states. */enum class CameraPermissionState(val displayName: String) {    /** Permission not yet requested. */    NOT_REQUESTED("Not Requested"),    /** Permission granted — camera can be used. */    GRANTED("Granted"),    /** User denied once — show rationale + retry. */    DENIED_ONCE("Denied Once"),    /** User denied twice — offer photo picker fallback. */    DENIED_TWICE("Denied Twice"),    /** User denied permanently (selected "Don't ask again") — guide to Settings. */    DENIED_PERMANENTLY("Denied Permanently");}/** Recovery actions for camera permission. */enum class CameraRecoveryAction(val displayName: String) {    /** Camera permission granted — proceed with camera. */    PROCEED_WITH_CAMERA("Proceed with Camera"),    /** Request camera permission (show system dialog). */    REQUEST_PERMISSION("Request Permission"),    /** Offer photo picker fallback (no camera needed). */    OFFER_PHOTO_PICKER("Offer Photo Picker"),    /** Offer photo picker OR guide to Settings. */    OFFER_PHOTO_PICKER_OR_SETTINGS("Offer Photo Picker or Settings"),    /** Guide user to Settings to enable camera manually. */    GUIDE_TO_SETTINGS("Guide to Settings"),}// ──────────────────────────────────────────────────────────────────────────/** * Photo picker result — either a selected image URI or user cancelled. */sealed interface PhotoPickerResult {    data class Selected(val imageUri: Uri, val imageBytes: ByteArray) : PhotoPickerResult {        override fun equals(other: Any?): Boolean {            if (this === other) return true            if (other !is Selected) return false            return imageUri == other.imageUri && imageBytes.contentEquals(other.imageBytes)        }        override fun hashCode(): Int {            return imageUri.hashCode() * 31 + imageBytes.contentHashCode()        }    }    data object Cancelled : PhotoPickerResult}